from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums)

        @lru_cache(maxsize=None)
        def dp(i: int, c: int) -> int:
            # Remaining elements (in order): nums[c], nums[i], nums[i+1], ..., nums[n-1]
            if n - i + 1 < 3:
                m = nums[c]
                for j in range(i, n):
                    if nums[j] > m:
                        m = nums[j]
                return m
            a, b, d = nums[c], nums[i], nums[i + 1]
            return min(
                max(a, b) + dp(i + 2, i + 1),
                max(a, d) + dp(i + 2, i),
                max(b, d) + dp(i + 2, c),
            )

        return dp(1, 0)
